<?php require 'admin_guard.php'; require 'admin_db.php'; $code=$_GET['coursecode']??''; $s=mysqli_prepare($conn,'SELECT admin FROM course WHERE coursecode=?');mysqli_stmt_bind_param($s,'s',$code);mysqli_stmt_execute($s);$c=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$c)die('Course not found');$admins=mysqli_fetch_assoc(mysqli_query($conn,'SELECT COUNT(*) total FROM admin_info'))['total'];$users=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) total FROM course_student_took WHERE coursecode='".mysqli_real_escape_string($conn,$code)."'"))['total'];$repos=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) total FROM repository WHERE coursecode='".mysqli_real_escape_string($conn,$code)."'"))['total'];$used=($users+$repos)>0;$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){if($admins<2){$msg='Cannot delete: at least two admins are required for consensus.';}else{$s=mysqli_prepare($conn,'SELECT requestID FROM admin_course_delete_requests WHERE coursecode=? AND status="PENDING"');mysqli_stmt_bind_param($s,'s',$code);mysqli_stmt_execute($s);$q=mysqli_stmt_get_result($s);$req=mysqli_fetch_assoc($q);if(!$req){$s=mysqli_prepare($conn,'INSERT INTO admin_course_delete_requests(coursecode,requestedBy) VALUES(?,?)');mysqli_stmt_bind_param($s,'ss',$code,$adminID);mysqli_stmt_execute($s);$rid=mysqli_insert_id($conn);mysqli_query($conn,"INSERT INTO admin_course_delete_votes(requestID,adminID,vote) VALUES($rid,'".mysqli_real_escape_string($conn,$adminID)."','YES')");$msg='Delete request sent. Other admins must vote; course owner must also vote YES.';}else{$msg='A pending deletion request already exists.';}}}
?>
<!doctype html><html><head><title>Delete Course</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="panel"><h1>Delete <?=htmlspecialchars($code)?></h1><p>Students using: <b><?=$users?></b> | Repositories using: <b><?=$repos?></b></p><?php if($used): ?><div class="notice">This course is currently in use. Confirming will create an admin consensus request.</div><?php else:?><div class="notice">No student/repository is currently using this course, but admin consensus is still required.</div><?php endif;?><?php if($msg)echo'<div class="notice">'.htmlspecialchars($msg).'</div>';?><form method="post"><label><input type="checkbox" required> I understand and want to request deletion.</label><button class="danger">Take Other Admins' Suggestion</button></form><br><a class="btn" href="course_delete_votes.php?coursecode=<?=urlencode($code)?>">View Votes</a></div></div></body></html>
